define(['exports','core/ajax','core/str'],function(exports,Ajax,Str){'use strict';Object.defineProperty(exports,'__esModule',{value:true});exports.init=void 0;const init=config=>{const button=document.getElementById(config.buttonId),status=document.getElementById(config.statusId),select=document.getElementById(config.selectId),knowledgeId=document.getElementById(config.knowledgeId),username=document.getElementById(config.usernameId),password=document.getElementById(config.passwordId),workspace=document.getElementById(config.workspaceId),selectedName=document.getElementById(config.nameId);if(!button||!select)return;const setStatus=(message,className='')=>{if(status){status.className=className;status.textContent=message}},reset=async()=>{while(select.firstChild)select.removeChild(select.firstChild);const option=document.createElement('option');option.value='';option.textContent=await Str.getString('chooseknowledgebase','mod_fredkisync');select.appendChild(option);if(knowledgeId)knowledgeId.value='';if(selectedName)selectedName.value=''},updateHiddenField=(field,value)=>{if(!field)return;field.value=value;field.dispatchEvent(new Event('input',{bubbles:true}));field.dispatchEvent(new Event('change',{bubbles:true}))},syncSelection=()=>{const option=select.options[select.selectedIndex],value=option&&option.value?option.value:'';updateHiddenField(knowledgeId,value);updateHiddenField(selectedName,value&&option?option.textContent.trim():'')};select.addEventListener('change',syncSelection);const form=select.closest('form');if(form)form.addEventListener('submit',syncSelection);button.addEventListener('click',async()=>{const previousValue=knowledgeId&&knowledgeId.value||select.value||'',userValue=username?username.value.trim():'',passwordValue=password?password.value:'';if(!userValue||!passwordValue){setStatus(await Str.getString('entercredentials','mod_fredkisync'),'alert alert-warning');return}button.disabled=true;await reset();setStatus(await Str.getString('loadingknowledgebases','mod_fredkisync'),'alert alert-info');try{const response=await Ajax.call([{methodname:'mod_fredkisync_get_knowledgebases',args:{courseid:config.courseId,username:userValue,password:passwordValue,workspace:workspace&&workspace.value||'default'}}])[0],items=Array.isArray(response.items)?response.items:[];items.forEach(item=>{const option=document.createElement('option');option.value=item.id;option.textContent=item.name;select.appendChild(option)});if(previousValue&&items.some(item=>String(item.id)===String(previousValue))){select.value=previousValue;syncSelection()}if(items.length===0){setStatus(await Str.getString('noknowledgebases','mod_fredkisync'),'alert alert-warning');return}setStatus(await Str.getString('knowledgebasesloaded','mod_fredkisync',items.length),'alert alert-success')}catch(error){setStatus(await Str.getString('knowledgebasesloadfailed','mod_fredkisync'),'alert alert-danger')}finally{button.disabled=false}})};exports.init=init;});